# build test pixels and find 4/8 comps after removing axis?
rows={7:[4,5,6,11,12,13],8:[6,11],9:[6,7,9,10,11,12],10:[6,7,8,9,12,13],11:[5,6,9],12:[4,5,9],13:[8,9,10,11,12,13]}
pix={(r,c) for r,cs in rows.items() for c in cs}
def comps(p, diag=False):
  out=[]
  while p:
    seed=p.pop(); comp={seed}; stack=[seed]
    while stack:
      r,c=stack.pop()
      ns=[(r+dr,c+dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (diag or abs(dr)+abs(dc)==1)]
      for n in ns:
        if n in p:p.remove(n);comp.add(n);stack.append(n)
    out.append(comp)
  return out
for diag in (False,True):
 c=comps(set(pix),diag); print(diag,[(len(x),(min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x))) for x in c])
